    const toggle = (name, desc, key, disabled = false) => new Setting(el).setName(name).setDesc(desc)
      .addToggle(t => t.setValue(p.settings[key]).setDisabled(disabled).onChange(async value => { await p.change(key, value); this.display(); }));
